package au.edu.uow.csci318.planning.controller;import au.edu.uow.csci318.planning.application.PlanningApplicationService;import au.edu.uow.csci318.planning.dto.PlanningDtos.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/planning") @CrossOrigin public class PlanningController{private final PlanningApplicationService service;public PlanningController(PlanningApplicationService s){service=s;}@GetMapping("/workload")public WorkloadSummary workload(){return service.workload();}@GetMapping("/this-week")public ThisWeek week(){return service.thisWeek();}@GetMapping("/plans/latest")public ResponseEntity<PlanResponse>latest(){return service.latest().map(ResponseEntity::ok).orElse(ResponseEntity.noContent().build());}@PostMapping("/plans")@ResponseStatus(HttpStatus.CREATED)public PlanResponse generate(@Valid@RequestBody PlanRequest r){return service.generate(r);}@PostMapping("/plans/{id}/regenerate")@ResponseStatus(HttpStatus.CREATED)public PlanResponse regenerate(@PathVariable UUID id,@Valid@RequestBody PlanRequest r){return service.regenerate(id,r);}}
